import{R as r}from"./index-BIQu6HMz.js";const p={async getAll(t){return r.get("/products",{params:t})},async search(t){return r.get("/products/search",{params:{q:t}})},async getById(t){return r.get(`/products/${t}`)},async create(t){return r.post("/products",t)},async update(t,e){return r.put(`/products/${t}`,e)},async delete(t){return r.delete(`/products/${t}`)},async bulkImport(t){return r.post("/products/import",t,{headers:{"Content-Type":"multipart/form-data"}})},async duplicate(t){return r.post(`/products/${t}/duplicate`)}};export{p};
